package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.service.MerchantActor;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcBusinessDashboardTest extends JdbcAssessmentSnapshotsTest {
 BusinessDashboard dashboards;
 @BeforeEach void business(){for(String t:List.of("merchant_commission_entry","order_commission_snapshot","merchant_commission_policy","merchant_application_review","merchant_application"))jdbc.update("DELETE FROM "+t);jdbc.update("UPDATE operator_account SET can_analytics=1 WHERE id=1");dashboards=new BusinessDashboard(db,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())),new DataSourceTransactionManager(jdbc.getDataSource()));}
 com.fasterxml.jackson.databind.JsonNode dashboard(){return db.mapper.valueToTree(dashboards.dashboard(operator,1,period));}
 com.fasterxml.jackson.databind.JsonNode bucket(com.fasterxml.jackson.databind.JsonNode r,String metric,String bucket){return r.path("metrics").path(metric).path(bucket);}
 long refund(long id,Instant at){jdbc.update("UPDATE `order` SET status='CLOSED',close_reason='REFUND_CANCELLED' WHERE id=?",id);long r=db.insert("INSERT INTO refund(order_id,payment_id,amount,status,refunded_at,owner_consented_at,merchant_consented_at,refund_no,channel_refund_no,from_status) VALUES(?,?,10,'SUCCEEDED',?,?,?,?,?,'COMPLETED')",id,id,ReservationStore.time(at),ReservationStore.time(at.minusSeconds(2)),ReservationStore.time(at.minusSeconds(1)),"R"+key().replace("-",""),"synthetic-refund-"+id);String channel=jdbc.queryForObject("SELECT channel FROM payment WHERE id=?",String.class,id);jdbc.update("INSERT INTO refund_event(channel,event_id,refund_id,event_hash,outcome) VALUES(?,?,?,?,'SUCCEEDED')",channel,key(),r,"d".repeat(64));return r;}
 void testPayment(long id){jdbc.update("UPDATE payment SET channel='LOCAL_TEST' WHERE id=?",id);jdbc.update("UPDATE payment_event SET channel='LOCAL_TEST' WHERE payment_id=?",id);jdbc.update("UPDATE order_redemption SET test_mode=1 WHERE order_id=?",id);}
 void commission(long id){Instant approved=start.atZone(ZoneId.of("Asia/Shanghai")).minusMonths(4).toInstant();jdbc.update("INSERT INTO merchant_application(id,applicant_user_id,merchant_name,category,region_code,status,merchant_id,reviewed_by,reviewed_at) VALUES(1,1,'synthetic','REPAIR','440106','APPROVED',1,1,?)",ReservationStore.time(approved));jdbc.update("INSERT INTO merchant_application_review(application_id,revision,decision,merchant_id,operator_id,decided_at) VALUES(1,1,'APPROVED',1,1,?)",ReservationStore.time(approved));db.transactions.executeWithoutResult(tx->{CommissionLedger.initialize(db,1,1,approved);CommissionLedger.booking(db,id);CommissionLedger.completed(db,id);});}
 @Test void independentPermissionNoImplicitAssessmentGrantAndCurrentSessionRequired(){prepare();jdbc.update("UPDATE operator_account SET can_analytics=0,can_assessment=1,can_coupon=1 WHERE id=1");assertEquals(403,code(()->dashboards.dashboard(operator,1,period)));assertEquals(403,code(()->dashboards.merchants(operator,1)));jdbc.update("UPDATE operator_account SET can_analytics=1 WHERE id=1");assertEquals(2L,dashboards.merchants(operator,1).get("total"));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",operator.session());assertEquals(401,code(()->dashboards.dashboard(operator,1,period)));}
 @Test void receiptsRefundsUseOwnMonthAndDifferenceCanBeNegative(){prepare();formalOrder(10,start.plusSeconds(1000),true);clock.value=end;var paid=dashboard();assertEquals("10.00",bucket(paid,"payments","formal").path("amount").asText());assertEquals("10.00",paid.path("cash_difference").path("formal").path("amount").asText());refund(10,end.plusSeconds(10));clock.value=end.plusSeconds(100);var previous=dashboard();assertEquals("0.00",bucket(previous,"refunds","formal").path("amount").asText());String next=end.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().toString().substring(0,7);var current=db.mapper.valueToTree(dashboards.dashboard(operator,1,next));assertEquals("0.00",bucket(current,"payments","formal").path("amount").asText());assertEquals("10.00",bucket(current,"refunds","formal").path("amount").asText());assertEquals("-10.00",current.path("cash_difference").path("formal").path("amount").asText());jdbc.update("UPDATE refund SET from_status='UNVERIFIED' WHERE order_id=10");var invalid=db.mapper.valueToTree(dashboards.dashboard(operator,1,next));assertTrue(bucket(invalid,"refunds","formal").path("amount").isNull());jdbc.update("UPDATE refund SET from_status='COMPLETED' WHERE order_id=10");jdbc.update("DELETE FROM order_redemption WHERE order_id=10");invalid=db.mapper.valueToTree(dashboards.dashboard(operator,1,next));assertTrue(bucket(invalid,"refunds","formal").path("amount").isNull());}
 @Test void testChannelIsSeparateAndDamagedReceiptHidesIncompleteFormalMoney(){prepare();formalOrder(10,start.plusSeconds(1000),true);formalOrder(11,start.plusSeconds(1100),true);testPayment(11);clock.value=end;var r=dashboard();assertEquals("10.00",bucket(r,"payments","formal").path("amount").asText());assertEquals("10.00",bucket(r,"payments","test").path("amount").asText());assertEquals(1,bucket(r,"orders_completed","test").path("count").asInt());jdbc.update("DELETE FROM payment_event WHERE payment_id=10");r=dashboard();assertEquals("UNKNOWN",bucket(r,"payments","formal").path("state").asText());assertTrue(bucket(r,"payments","formal").path("amount").isNull());assertTrue(r.path("cash_difference").path("formal").path("amount").isNull());assertEquals("10.00",bucket(r,"payments","test").path("amount").asText());}
 @Test void ambiguousChannelOrLegacyIdentityNeverBecomesFormalZero(){prepare();formalOrder(10,start.plusSeconds(1000),true);clock.value=end;assertEquals(1,dashboard().path("metrics").path("orders_created").path("unclassified_count").asInt());jdbc.update("UPDATE payment SET channel='UNVERIFIED' WHERE id=10");var r=dashboard();assertEquals(1,r.path("metrics").path("payments").path("unclassified_count").asInt());assertEquals("UNKNOWN",bucket(r,"payments","formal").path("state").asText());assertEquals("UNKNOWN",bucket(r,"payments","test").path("state").asText());}
 @Test void cashReturnUpdatesOriginalUseButDoesNotOverwriteFrozenAssessment(){prepare();formalOrder(10,start.plusSeconds(1000),true);long uc=coupon("DISCOUNT");cash(10,uc);var frozen=settle(0);long refund=refund(10,end.plusSeconds(10));jdbc.update("UPDATE order_coupon_allocation SET state='RETURNED' WHERE order_id=10");jdbc.update("INSERT INTO coupon_transaction_event(user_coupon_id,event_key,kind,order_id,payment_id,refund_id,before_status,after_status,rule_version,occurred_at) VALUES(?,'synthetic-business-return','REFUND_RETURN',10,10,?,'USED','AVAILABLE','R5B_CASH_V1',?)",uc,refund,ReservationStore.time(end.plusSeconds(10)));clock.value=end.plusSeconds(100);var r=dashboard();assertEquals(0,bucket(r,"cash_coupon_uses","formal").path("count").asInt());assertEquals(1,bucket(r,"cash_coupon_uses","formal").path("excluded_count").asInt());assertEquals(frozen.path("revision").asInt(),r.path("assessment").path("revision").asInt());assertEquals("40.00",r.path("assessment").path("total_score").asText());assertEquals(1,count("assessment_snapshot"));}
 @Test void serviceAndNewCustomerUsePermanentProofAndUnknownIdentityStaysUnknown(){prepare();service(coupon("SERVICE"));clock.value=end;assertEquals("UNKNOWN",bucket(dashboard(),"service_coupon_uses","formal").path("state").asText());invitation("VERIFIED_WECHAT");var r=dashboard();assertEquals(1,bucket(r,"service_coupon_uses","formal").path("count").asInt());assertEquals(1,bucket(r,"new_customers","formal").path("count").asInt());jdbc.update("DELETE FROM invite_phone_evidence");assertEquals("UNKNOWN",bucket(dashboard(),"new_customers","formal").path("state").asText());}
 @Test void commissionsUseFrozenSourceAndCrossMonthReversalIsNotPaidFunds(){prepare();formalOrder(10,start.plusSeconds(1000),true);commission(10);clock.value=end;assertEquals("0.30",bucket(dashboard(),"commission_accrual","formal").path("amount").asText());long r=refund(10,end.plusSeconds(10));db.transactions.executeWithoutResult(tx->CommissionLedger.refunded(db,db.one("SELECT * FROM `order` WHERE id=10"),db.one("SELECT * FROM payment WHERE id=10"),db.one("SELECT * FROM refund WHERE id=?",r)));clock.value=end.plusSeconds(100);String next=end.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().toString().substring(0,7);var result=db.mapper.valueToTree(dashboards.dashboard(operator,1,next));assertEquals("-0.30",bucket(result,"commission_accrual","formal").path("amount").asText());jdbc.update("UPDATE merchant_commission_entry SET rule_version='UNVERIFIED' WHERE event_key='REFUND'");result=db.mapper.valueToTree(dashboards.dashboard(operator,1,next));assertTrue(bucket(result,"commission_accrual","formal").path("amount").isNull());}
 @Test void missingCommissionEvidenceIsUnknownAndReadsHaveNoSideEffects(){prepare();formalOrder(10,start.plusSeconds(1000),true);clock.value=end;int audit=count("audit_log"),receipts=count("idempotency_record");var r=dashboard();assertEquals("UNKNOWN",bucket(r,"commission_accrual","formal").path("state").asText());assertEquals(0,count("order_commission_snapshot"));assertEquals(0,count("merchant_commission_entry"));assertEquals(0,count("assessment_snapshot"));assertEquals(audit,count("audit_log"));assertEquals(receipts,count("idempotency_record"));assertFalse(r.toString().contains("user_id"));assertFalse(r.toString().contains("payment_no"));assertFalse(r.toString().contains("verify_code"));}
 @Test void managerScopeCannotBeSelectedByEmployeeAndOtherStoreStaysEmpty(){prepare();formalOrder(10,start.plusSeconds(1000),true);clock.value=end;var a=db.mapper.valueToTree(dashboards.dashboard(merchant,period));var b=db.mapper.valueToTree(dashboards.dashboard(other,period));assertEquals("10.00",bucket(a,"payments","formal").path("amount").asText());assertEquals("0.00",bucket(b,"payments","formal").path("amount").asText());var staff=new MerchantActor(1,1,"STAFF",merchant.session(),merchant.expires());assertEquals(403,code(()->dashboards.dashboard(staff,period)));}
 @Test void monthBoundsAndCurrentObservationExcludeFutureEvents(){prepare();formalOrder(10,start.plusSeconds(900),true);formalOrder(11,start.plusSeconds(1100),true);clock.value=start.plusSeconds(1000);var r=dashboard();assertEquals(clock.value.toString(),r.path("window_to").asText());assertEquals(1,bucket(r,"payments","formal").path("count").asInt());String future=end.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().toString().substring(0,7);assertEquals(409,code(()->dashboards.dashboard(operator,1,future)));assertEquals(400,code(()->dashboards.merchants(operator,0)));}
}
